<template>
  <div
    class="crosshair"
    :style="{
      transform: `rotate(${settings.rotation}deg)`,
      marginRight: `${settings.offsetRight}px`,
      marginTop: `${settings.offsetTop}px`,
    }"
  >
    <div
      :style="{
        borderRadius: `${settings.radius}%`,
        background: settings.color,
        height: `${settings.size}px`,
        width: `${settings.width}px`,
        opacity: settings.sideLeft ? '1' : '0',
        border: settings.outlineEnabled
          ? `solid ${settings.outlineWidth}px ${settings.outlineColor}`
          : `none`,
      }"
      class="crosshair-top"
    ></div>
    <div class="flex items-center">
      <div
        :style="{
          borderRadius: `${settings.radius}%`,
          background: settings.color,
          width: `${settings.size}px`,
          height: `${settings.width}px`,
          opacity: settings.sideTop ? '1' : '0',
          border: settings.outlineEnabled
            ? `solid ${settings.outlineWidth}px ${settings.outlineColor}`
            : `none`,
        }"
        class="crosshair-left"
        id="testfix"
      ></div>
      <div
        class="crosshair-dot"
        :style="{ height: `${settings.gap}px`, width: `${settings.gap}px` }"
      >
        <div
          v-if="settings.dotEnabled"
          :style="{
            borderRadius: `${settings.dotRadius}%`,
            background: settings.dotColor,
            height: `${settings.dotSize}px`,
            width: `${settings.dotSize}px`,
            border: settings.outlineEnabled
              ? `solid ${settings.outlineWidth}px ${settings.outlineColor}`
              : `none`,
          }"
        ></div>
      </div>
      <div
        :style="{
          borderRadius: `${settings.radius}%`,
          background: settings.color,
          width: `${settings.size}px`,
          height: `${settings.width}px`,
          opacity: settings.sideRight ? '1' : '0',
          border: settings.outlineEnabled
            ? `solid ${settings.outlineWidth}px ${settings.outlineColor}`
            : `none`,
        }"
        class="crosshair-right"
      ></div>
    </div>
    <div
      :style="{
        borderRadius: `${settings.radius}%`,
        background: settings.color,
        height: `${settings.size}px`,
        width: `${settings.width}px`,
        opacity: settings.sideBottom ? '1' : '0',
        border: settings.outlineEnabled
          ? `solid ${settings.outlineWidth}px ${settings.outlineColor}`
          : `none`,
      }"
      class="default-bottom"
    ></div>
  </div>
</template>

<script>
export default {
  name: "CrossType",
  props: ["settings"],
  mounted() {
    console.log(this.settings);
  },
};
</script>

<style lang="scss" scoped>
.crosshair {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.crosshair-dot {
  overflow: visible;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;

  div {
    position: absolute;
  }
}
</style>
